/**
 * Battle DTOs for Fantasy Autobattler API.
 * Swagger documentation for battle-related endpoints and responses with validation.
 * 
 * @fileoverview DTO classes for battle data with comprehensive API documentation and validation.
 */

import { ApiProperty } from '@nestjs/swagger';
import { IsOptional, IsString, IsEnum } from 'class-validator';

/**
 * Core 2.0 Mechanic Event Types.
 * All event types generated by the modular mechanics system.
 */
export enum MechanicEventType {
  /** Facing: Unit changes facing direction (Tier 0) */
  FACING = 'mechanic_facing',
  
  /** Resolve: Morale damage, regeneration, or break (Tier 1) */
  RESOLVE = 'mechanic_resolve',
  
  /** Routing: Unit retreats or crumbles due to zero resolve (Tier 1) */
  ROUTING = 'mechanic_routing',
  
  /** Engagement: Zone of Control applied (Tier 1) */
  ENGAGEMENT = 'mechanic_engagement',
  
  /** Attack of Opportunity: Free attack when enemy leaves ZoC (Tier 1) */
  ATTACK_OF_OPPORTUNITY = 'mechanic_aoo',
  
  /** Flanking: Damage modifier from attack arc (front/flank/rear) (Tier 1) */
  FLANKING = 'mechanic_flanking',
  
  /** Riposte: Counter-attack after being attacked (Tier 2) */
  RIPOSTE = 'mechanic_riposte',
  
  /** Intercept: Hard intercept (stop cavalry) or soft intercept (engage) (Tier 2) */
  INTERCEPT = 'mechanic_intercept',
  
  /** Aura: Area effect applied to nearby units (Tier 2) */
  AURA = 'mechanic_aura',
  
  /** Charge: Cavalry momentum bonus from movement (Tier 3) */
  CHARGE = 'mechanic_charge',
  
  /** Overwatch: Ranged reaction shot during enemy movement (Tier 3) */
  OVERWATCH = 'mechanic_overwatch',
  
  /** Phalanx: Formation bonuses from adjacent allies (Tier 3) */
  PHALANX = 'mechanic_phalanx',
  
  /** Line of Sight: Direct fire blocked or arc fire penalty (Tier 3) */
  LINE_OF_SIGHT = 'mechanic_los',
  
  /** Ammunition: Ammo consumed or reloaded (Tier 3) */
  AMMUNITION = 'mechanic_ammo',
  
  /** Contagion: Status effect spreads to adjacent units (Tier 4) */
  CONTAGION = 'mechanic_contagion',
  
  /** Armor Shred: Armor reduction from physical attacks (Tier 4) */
  ARMOR_SHRED = 'mechanic_armor_shred',
}

